以下第21-26题基于以下程序：

```cpp
#include<iostream>
int main() {
    int d;
    std::cin >> d;
    char s[1000];
    int size = 0;
    char c;
    while (std::cin >> c) {
        while (size > 0 and d > 0) {
            char top = s[size - 1];
            if (top < c) {
                d--;
                size--;
            }
            else {
                break;
            }
        }
        s[size++] = c;
    }
    while (d > 0) {
        d--;
        size--;
    }
    for (int i = 0; i < size; ++i) {
        std::cout << s[i];
    }
}
```

把 while (size > 0 and d > 0) 改成 while (size >= 0 and d > 0) 后程序功能保持不变。

以下第27-34题基于以下程序：

```cpp
#include<iostream>
int choose[20];
int dfs(int m, int n) {
    if (m == n) {
        bool flag = true;
        for (int i = 0; i + 1 < n; ++i) {
            if (choose[i] && choose[i+1]) {
                flag = false;
            }
        }
        if (flag) {
            return 1;
        }
        else {
            return 0;
        }
    }
    else {
        choose[m] = true;
        int pick = dfs(m+1, n);
        choose[m] = false;
        int drop = dfs(m+1, n);
        return pick + drop;
    }
}

int fib(int n) {
    int f[21];
    f[0] = 1;
    f[1] = 2;
    for (int i = 2; i <= n; ++i) {
        f[i] = f[i-1] + f[i-2];
    }
    return f[n];
}

int main() {
    int n;
    std::cin >> n;
    std::cout << dfs(0, n) << " ";
    std::cout << fib(n) << "\n";
}
```

当 n 的输入值介于 0 到 20 之间时，dfs(0,n) 的返回值永远等于 fib(n)。

